package com.ggiova.gallery.data;

/**
 * Represents an item's variant, as in, an image or video and it's thumbnails.
 *
 * @param id          Unique autogenerated long identification.
 * @param itemId     Foreign key that connects to {@link Item}.
 * @param kind        Represents the type stored, see {@link VariantKind}
 * @param storagePath Relative path of where the file can be found.
 * @param mime        label for the type of file, following the "[category]/[format]" structure.
 *                    For example: "image/png" or "video/mp4".
 */
public record Variant(
        long id,
        long itemId,
        VariantKind kind,
        String storagePath,
        String mime
) {}